/* Corps v3 en kraft : ~70 plans courts, chacun calé sur un mot de la voix : at = [phrase, mot] */
const V = [], v = (at, o) => V.push(Object.assign(o, { at }));
const AT = (s, w) => ALLWORDS[s][w].start, loc = (self, s, w) => AT(s, w) - self._start;
const pp = K.pop, Cc = K.C, CX = 540;
const TONE = ["#F3D9C2", "#E8BE9B", "#CF9A72", "#A9704B", "#7C4A30", "#4B2B1E"];
const pool = (p, n, r) => Array.from({ length: n }, (_, i) => K.spot(p, 0, 0, r, i + 1));
const rise = (ds, t, cx, y0, y1, spread, speed, amt = 1) => ds.forEach((q, i) => { const ph = (t * speed + i / ds.length) % 1, on = i / ds.length < amt; H.set(q, { x: cx + Math.sin(i * 2.3 + t * 2) * spread, y: lerp(y0, y1, E.out(ph)), s: on ? (.4 + .6 * Math.min(1, ph * 3)) : 0, o: on && ph < .96 ? 1 : 0 }); });

const WX = 540, WY = 835, WS = 1.12;
const PERS = [{ skin: "#9C6243", hair: "#1D130E", hairStyle: "bun", top: "#8DB6D6" }, { skin: "#B27A55", hair: "#2A1810", hairStyle: "long", top: "#E9B8A0" }, { skin: "#7A4A32", hair: "#1D130E", hairStyle: "braids", top: "#7FA283" }, { skin: "#A06A47", hair: "#1D130E", hairStyle: "wrap", top: "#F2E7BA", wrap: "#D2452F" }, { skin: "#6B4130", hair: "#140D0A", hairStyle: "curly", top: "#E0A93C" }, { skin: "#C68863", hair: "#2A1810", hairStyle: "bob", top: "#B7A3D0" }];
const HW = (L, o = {}) => { const pr = PERS[(o.pr === undefined ? 0 : o.pr) % PERS.length]; return K.woman(L, o.x || WX, o.y || WY, o.s || WS, Object.assign({}, pr, o)); };
const sway = (w, t, a = 1) => { H.set(w.s, { r: Math.sin(t * 2.2) * .8 * a }); H.set(w.head, { r: Math.sin(t * 1.7) * 2 * a }); };
const FSP = [[-72, 40, 11], [-90, 70, 8], [-54, 76, 9], [72, 44, 12], [92, 74, 8], [56, 80, 9], [-30, 100, 7], [34, 106, 8], [8, -44, 9], [-34, -66, 7]];
const cover = (w, col = "#D8A67B") => FSP.map((q, i) => { const g = H.grp(w.head, q[0], q[1], { j: .3 }); H.blob(g, 0, 0, q[2] * 2.1, q[2] * 1.9, col, { seed: i + 40, jit: .1, sh: "sh1", th: 2 }); return g; });
const flame = (p) => { const f = H.grp(p, 0, 0, { j: .9 }); H.poly(f, [[0, -90], [36, -40], [30, 20], [0, 40], [-30, 20], [-40, -36], [-14, -26]], "#E8742E", { seed: 7, jit: 1.5 }); H.poly(f, [[0, -40], [16, -4], [0, 22], [-16, -4]], "#FFD58A", { seed: 8, jit: 1, sh: false }); return f; };
const rub = (w, t, p, a, b, cx, cy, rx, ry, n = 3) => { const r = seg(p, a, b); w.reach("R", cx + Math.sin(r * Math.PI * 2 * n) * rx, cy + Math.cos(r * Math.PI * n) * ry); };

const botW = (L, pr, o = {}) => HW(L, Object.assign({ pr, x: 540, y: 1035, s: .66 }, o));
const botPose = (w, t, p, o = {}) => { w.reach("L", o.lx !== undefined ? o.lx : -130, o.ly !== undefined ? o.ly : -260); w.reach("R", 170, 40); w.exp({ brow: o.brow !== undefined ? o.brow : -.3, mouth: o.mouth || "smile", eyes: o.eyes || "open" }); sway(w, t, .6); };
const sweep = (g, t, p, a, b, cx, cy, rx, ry, n = 4) => { const r = seg(p, a, b); H.set(g, { x: cx + Math.sin(r * Math.PI * 2 * n) * rx, y: cy + Math.cos(r * Math.PI * n) * ry, r: Math.sin(r * Math.PI * 2 * n) * 10, o: r > 0 && r < 1 ? 1 : 0 }); };
const title = (L, txt, y = 330, o = {}) => K.label(L, txt, CX, y, Object.assign({ size: 64, maxw: 740 }, o));
const numTitle = (self, L, n, txt, col) => { self.bd = K.badge(L, n, 190, 290, col); self.tt = K.label(L, txt, 640, 290, { size: 56, maxw: 560, pad: [34, 18] }); };
const numIn = (self, p) => { pp(self.bd, p, .02, .2); H.set(self.tt, { x: lerp(1300, 630, E.out(seg(p, .05, .3))), o: p > .05 ? 1 : 0 }); };
const trig = (at, id, tone, lab, mk, sfx) => v(at, { id, sfx,
  init(L) { K.panel(L.bg, tone); this.tt = title(L.mid, lab); this.ob = mk(L.mid); this.ce = K.cell(L.mid, 760, 900, 1.5); this.ar = K.arrow(L.mid, 480, 790, 640, 850, Cc.red, 40); this.bu = K.burst(L.mid, 90, 130, 12, Cc.red); H.set(this.ob, { x: 290, y: 760 }); },
  update(t, p, d, L) { H.look(L, 0, 0, lerp(1, 1.06, p)); pp(this.tt, p, .02, .18); pp(this.ob, p, .05, .25); H.set(this.ar, { sx: E.out(seg(p, .3, .5)), o: p > .3 ? 1 : 0 }); const k = seg(p, .5, .7); H.set(this.bu, { x: 760, y: 870, s: E.pop(k) * (1 + .1 * Math.sin(t * 14)), o: k > 0 ? .95 : 0, r: t * 40 }); H.set(this.ce.q, { s: 1 + .08 * Math.sin(t * 18) * seg(p, .5, 1) }); } });

/* ---------- intro ---------- */
v([0, 0], { id: "five", sfx: [[.05, "paper"], [.2, "stamp"], [.55, "pop"]],
  init(L) { K.panel(L.bg, "terra"); this.bu = K.burst(L.mid, 340, 410, 18, Cc.cream); this.n = H.grp(L.mid, 540, 640, { j: .6 }); H.txt(this.n, "5", 0, 205, 560, Cc.terraD, { font: "Anton, sans-serif", w: 400 }); this.lb = K.label(L.mid, "RAISONS", 540, 1060, { size: 100, fill: Cc.brown, ink: Cc.cream, maxw: 780 }); },
  update(t, p, d, L) { H.look(L, 0, 0, lerp(1, 1.05, p)); H.set(this.bu, { x: 540, y: 640, r: t * 8, s: E.pop(seg(p, .05, .3)), o: p > .05 ? 1 : 0 }); pp(this.n, p, .08, .34); H.set(this.lb, { s: E.pop(H.clamp((t - loc(this, 0, 1)) / .25)), o: t > loc(this, 0, 1) ? 1 : 0 }); } });
